-- Lookup: ProjectedScore from related Rosters


CREATE OR REPLACE FUNCTION calc_matchups_team2_score(p_matchup_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_rosters_projected_score((SELECT team2 FROM matchups WHERE matchup_id = p_matchup_id));
$$ LANGUAGE sql STABLE;

-- calc_matchups_name
-- Field: Matchups.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_matchups_name(p_matchup_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(matchup_id, '') FROM matchups WHERE matchup_id = p_matchup_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_matchups_margin
-- Field: Matchups.Margin
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_matchups_margin(p_matchup_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_matchups_team1_score(p_matchup_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_matchups_team2_score(p_matchup_id)) AS v OFFSET 0) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_matchups_winner
-- Field: Matchups.Winner
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_matchups_winner(p_matchup_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_matchups_margin(p_matchup_id))::NUMERIC, 0) > 0 THEN ((SELECT NULLIF(team1, '') FROM matchups WHERE matchup_id = p_matchup_id))::text ELSE ((SELECT NULLIF(team2, '') FROM matchups WHERE matchup_id = p_matchup_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_matchups_loser
-- Field: Matchups.Loser
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_matchups_loser(p_matchup_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_matchups_margin(p_matchup_id))::NUMERIC, 0) > 0 THEN ((SELECT NULLIF(team2, '') FROM matchups WHERE matchup_id = p_matchup_id))::text ELSE ((SELECT NULLIF(team1, '') FROM matchups WHERE matchup_id = p_matchup_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_matchups_is_tie_game
-- Field: Matchups.IsTieGame
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_matchups_is_tie_game(p_matchup_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_matchups_margin(p_matchup_id))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_standings_name
-- Field: Standings.Name
-- Type: calculated | DataType: string | Returns: TEXT
-- Lookup: Name from related Rosters


CREATE OR REPLACE FUNCTION calc_standings_name(p_standing_id TEXT)
RETURNS TEXT AS $$
  SELECT calc_rosters_name((SELECT standing_id FROM standings WHERE standing_id = p_standing_id));
$$ LANGUAGE sql STABLE;

-- calc_standings_owner
-- Field: Standings.Owner
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Owner from related Rosters


CREATE OR REPLACE FUNCTION calc_standings_owner(p_standing_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT owner::text FROM rosters WHERE roster_id = (SELECT standing_id FROM standings WHERE standing_id = p_standing_id));
$$ LANGUAGE sql STABLE;

